1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { readdirSync, existsSync, readFileSync } from 'node:fs';
4	import { join, dirname } from 'node:path';
5	import { fileURLToPath } from 'node:url';
6	import pack from '../pack.mjs';
7	import tidyIssues from '../tasks/tidy-issues/task.mjs';
8	import tidyPrs from '../tasks/tidy-prs/task.mjs';
9	import tidyBranches from '../tasks/tidy-branches/task.mjs';
10	
11	const PACK_DIR = join(dirname(fileURLToPath(import.meta.url)), '../../../packs/tidy-repo');
12	const taskDir = (id) => join(PACK_DIR, 'tasks', id);
13	
14	// The scheduler's signal bundle, in the shapes the collectors produce.
15	const S = (over = {}) => ({
16	  prs: { open: [], touched: [] },
17	  issues: { open: [], touched: [] },
18	  branches: { names: [], touched: [] },
19	  commits: { substantiveChange: false },
20	  ...over,
21	});
22	
23	test('tidy-repo is a declared pack (no fingerprint) with its skills; its tasks are not pack.mjs slots', () => {
24	  // No fingerprint is stated by saying nothing — the loader resolves an undeclared
25	  // `detect` to null.
26	  assert.equal(pack.detect, undefined);
27	  // The tasks moved out of the manifest: the repo's scheduler finds
28	  // tasks/<name>/task.mjs structurally (#394).
29	  assert.equal(pack.run_daily, undefined);
30	  assert.deepEqual(
31	    readdirSync(join(PACK_DIR, 'skills')).sort(),
32	    ['single-branch-status', 'single-issue-triage', 'single-pr-status'],
33	    'the worker skills are bundled in this pack\'s own skills/'
34	  );
35	});
36	
37	test('one task per tidy dimension — the single repo-tidy pass is split three ways', () => {
38	  assert.deepEqual(readdirSync(join(PACK_DIR, 'tasks')).sort(), ['tidy-branches', 'tidy-issues', 'tidy-prs']);
39	});
40	
41	test('every tidy task: id matches its dir, sonnet, outcome none, bounded, worker doc present', () => {
42	  for (const t of [tidyIssues, tidyPrs, tidyBranches]) {
43	    assert.ok(existsSync(taskDir(t.id)), `${t.id} has no task directory of its own`);
44	    assert.equal(t.agent_model, 'sonnet');    // landed-status / implemented-in-main are judgment calls
45	    assert.equal(t.expected_outcome, 'none'); // no tidy dimension ever opens or merges a PR
46	    assert.ok(Number.isInteger(t.agent_execution_timeout) && t.agent_execution_timeout > 0);
47	    assert.ok(existsSync(join(taskDir(t.id), t.agent_instructions)), `worker doc missing: ${t.id}/${t.agent_instructions}`);
48	  }
49	});
50	
51	// --- tidy-issues: the acting dimension, daily, narrow ------------------------
52	
53	test('tidy-issues: daily, and its signals are exactly the two triggers that change an issue verdict', () => {
54	  assert.equal(tidyIssues.id, 'tidy-issues');
55	  assert.equal(tidyIssues.frequency, 'daily'); // the one dimension that ACTS, so latency matters
56	  assert.deepEqual(tidyIssues.precondition_signals, ['issues', 'commits']);
57	});
58	
59	test('tidy-issues: scope is the touched issues only — a PR or branch moving is not its business', () => {
60	  const v = tidyIssues.precondition(S({ issues: { open: [{ number: 3 }, { number: 5 }], touched: [5] } }));
61	  assert.equal(v.run, true);
62	  assert.match(v.context.join(' '), /Issues to triage: #5\./);
63	  assert.doesNotMatch(v.context.join(' '), /#3/); // untouched, and main didn't move
64	
65	  // Activity in the other dimensions never wakes this task.
66	  assert.equal(tidyIssues.precondition(S({ prs: { open: [{ number: 7 }], touched: [7] } })).run, false);
67	  assert.equal(tidyIssues.precondition(S({ branches: { names: ['main', 'feat-x'], touched: ['feat-x'] } })).run, false);
68	});
69	
70	test('tidy-issues: a substantive main move widens an already-triggered run to every open issue', () => {
71	  const v = tidyIssues.precondition(S({
72	    issues: { open: [{ number: 3 }, { number: 5 }], touched: [5] },
73	    commits: { substantiveChange: true },
74	  }));
75	  assert.equal(v.run, true);
76	  assert.match(v.reason, /substantively/);
77	  assert.match(v.context.join(' '), /Issues to triage: #3, #5\./); // #3 is untouched, and still in scope
78	});
79	
80	// The gate the owner asked for: nothing new in the window → don't go over the
81	// existing ones. A moving `main` is not an issue moving, and on any active repo it
82	// moves substantively most days — so widening on it ALONE re-triaged every open
83	// issue daily, which is the failure this asserts against.
84	test('tidy-issues: a substantive main move alone never wakes the task', () => {
85	  const v = tidyIssues.precondition(S({
86	    issues: { open: [{ number: 3 }, { number: 5 }], touched: [] },
87	    commits: { substantiveChange: true },
88	  }));
89	  assert.equal(v.run, false);
90	  assert.match(v.reason, /no issues touched/);
91	});
92	
93	test('tidy-issues: silent on a quiet repo, and on a substantive move with no open issues', () => {
94	  assert.equal(tidyIssues.precondition(S()).run, false);
95	  assert.equal(tidyIssues.precondition(S({ commits: { substantiveChange: true } })).run, false);
96	});
97	
98	// --- tidy-prs: assess-only, weekly, full every run --------------------------
99	
100	test('tidy-prs: weekly (the full sweep is the declaration) over the prs signal alone', () => {
101	  assert.equal(tidyPrs.id, 'tidy-prs');
102	  assert.equal(tidyPrs.frequency, 'weekly');
103	  assert.deepEqual(tidyPrs.precondition_signals, ['prs']);
104	});
105	
106	test('tidy-prs: touched-ness gates the sweep but never narrows it — scope stays every open PR', () => {
107	  const v = tidyPrs.precondition(S({ prs: { open: [{ number: 7 }, { number: 9 }], touched: [9] } }));
108	  assert.equal(v.run, true);
109	  assert.match(v.reason, /full sweep over 2 open PR/);
110	  assert.match(v.context.join(' '), /PRs to assess.*#7, #9/); // #7 is untouched, and still assessed
111	  assert.match(v.context.join(' '), /read-only/);
112	});
113	
114	// The gate the owner asked for: an unchanged set of open PRs is last run's picture,
115	// and re-deriving it rewrites the tracker with itself.
116	test('tidy-prs: open PRs that nothing touched in the window are not re-swept', () => {
117	  const v = tidyPrs.precondition(S({ prs: { open: [{ number: 7 }, { number: 9 }], touched: [] } }));
118	  assert.equal(v.run, false);
119	  assert.match(v.reason, /no PR opened or updated in the window/);
120	});
121	
122	test('tidy-prs: no open PRs, no run', () => {
123	  assert.equal(tidyPrs.precondition(S()).run, false);
124	});
125	
126	// The `prs` signal also carries recently-MERGED PRs (for growth-extract). A merged
127	// PR is not something this sweep can recommend closing, so it must stay out of the
128	// target set entirely — the reason merged PRs live in their own field rather than
129	// being folded into `open`.
130	test('tidy-prs: merged PRs on the signal never enter the sweep', () => {
131	  const merged = { merged: [{ number: 42, title: 'landed last night' }] };
132	  assert.equal(tidyPrs.precondition(S({ prs: { open: [], touched: [], ...merged } })).run, false);
133	  // A merged PR is not a touch either: it cannot trigger the sweep on its own.
134	  assert.equal(tidyPrs.precondition(S({ prs: { open: [{ number: 7 }], touched: [], ...merged } })).run, false);
135	  const v = tidyPrs.precondition(S({ prs: { open: [{ number: 7 }], touched: [7], ...merged } }));
136	  assert.match(v.reason, /over 1 open PR/);
137	  assert.doesNotMatch(v.context.join(' '), /#42/);
138	});
139	
140	// --- tidy-branches: assess-only, weekly, full every run ---------------------
141	
142	test('tidy-branches: weekly (the full sweep is the declaration) over the branches signal alone', () => {
143	  assert.equal(tidyBranches.id, 'tidy-branches');
144	  assert.equal(tidyBranches.frequency, 'weekly');
145	  assert.deepEqual(tidyBranches.precondition_signals, ['branches']);
146	});
147	
148	test('tidy-branches: scope is every branch past the presumed default', () => {
149	  const v = tidyBranches.precondition(S({ branches: { names: ['main', 'feat-x', 'fix-y'], touched: ['fix-y'] } }));
150	  assert.equal(v.run, true);
151	  assert.match(v.reason, /full sweep over 2 branch/);
152	  assert.match(v.context.join(' '), /Branches to assess.*feat-x, fix-y/); // feat-x didn't move, and is still assessed
153	  assert.doesNotMatch(v.context.join(' '), /main/);
154	});
155	
156	// The gate the owner asked for. Branches are the dimension where it was structurally
157	// impossible before: the signal carried names and nothing else, so "is any of this
158	// new" had no answer and the sweep ran over the same pile every week.
159	test('tidy-branches: a standing pile of branches that nothing moved is not re-swept', () => {
160	  const v = tidyBranches.precondition(S({ branches: { names: ['main', 'feat-x', 'fix-y'], touched: [] } }));
161	  assert.equal(v.run, false);
162	  assert.match(v.reason, /no branch created or moved in the window/);
163	
164	  // A move on the default branch or an infra branch is not branch work either — it
165	  // is `main` advancing and the log stream growing, which happens on every repo
166	  // most days and would defeat the gate outright.
167	  assert.equal(tidyBranches.precondition(S({
168	    branches: { names: ['main', 'conversation-logs', 'feat-x'], touched: ['main', 'conversation-logs'] },
169	  })).run, false);
170	});
171	
172	test('tidy-branches: ignores the orphan conversation-logs and the maintenance delivery branch', () => {
173	  // conversation-logs is a claudinite-growth log stream and
174	  // claudinite/maintenance is Claudinite's own delivery branch — never project
175	  // work, so neither may reach the branch review.
176	  const v = tidyBranches.precondition(S({
177	    branches: { names: ['main', 'conversation-logs', 'claudinite/maintenance', 'feat-x'], touched: ['feat-x'] },
178	  }));
179	  assert.equal(v.run, true);
180	  assert.match(v.context.join(' '), /Branches to assess.*feat-x/);
181	  assert.doesNotMatch(v.context.join(' '), /conversation-logs|claudinite\/maintenance/);
182	
183	  // A repo whose only non-default branches are those two has no branch work at all.
184	  assert.equal(tidyBranches.precondition(S({ branches: { names: ['master', 'conversation-logs'], touched: ['conversation-logs'] } })).run, false);
185	  assert.equal(tidyBranches.precondition(S()).run, false);
186	});
187	
188	// --- the trackers: one per task, never a shared body ------------------------
189	
190	test('each worker reconciles its OWN tracker by exact title — three tasks never race on one body', () => {
191	  const titles = {
192	    'tidy-issues': 'Claudinite tracker: Tidy Issues',
193	    'tidy-prs': 'Claudinite tracker: Tidy PRs',
194	    'tidy-branches': 'Claudinite tracker: Tidy Branches',
195	  };
196	  for (const [id, title] of Object.entries(titles)) {
197	    const worker = readFileSync(join(taskDir(id), 'task.md'), 'utf8');
198	    assert.ok(worker.includes(`\`${title}\``), `${id}/task.md does not name its tracker \`${title}\``);
199	    // The tracker's state carries no meaning, so no worker may open or close it.
200	    assert.match(worker, /Never open, close, or reopen the tracker/);
201	    // The tracker logs changes, not scans: a run that acted on nothing (issues) or
202	    // re-derived the same picture (PRs, branches) leaves it untouched, and a repo
203	    // with nothing to record never gets a tracker at all.
204	    assert.match(worker, /nothing to record/, `${id}/task.md does not gate its tracker write on having something to record`);
205	  }
206	});
207	
208	// The self-trigger the touched-gate could not see (#988): a triage comment is an
209	// issue update, so a run that re-announces a verdict it already posted is the next
210	// window's `touched` and wakes itself, indefinitely. The fix is to not make that
211	// write — so the skill's no-repeat rule, and the marker that lets a run recognise
212	// its own prior verdict, are what these assert.
213	test('single-issue-triage: an unchanged verdict is posted nowhere, and carries its own action name', () => {
214	  const skill = readFileSync(join(PACK_DIR, 'skills/single-issue-triage/SKILL.md'), 'utf8');
215	  assert.match(skill, /post nothing and change nothing/i,
216	    'single-issue-triage does not forbid re-posting a verdict it already posted');
217	  assert.match(skill, /<!-- claudinite:tidy-issues verdict=/,
218	    'single-issue-triage defines no marker, so a run cannot recognise its own prior verdict');
219	  assert.match(skill, /\bunchanged\b/,
220	    'the return vocabulary carries no `unchanged`, so the worker cannot tell it apart from `left`');
221	});
222	
223	test('tidy-issues: its worker knows an unchanged verdict is not an action', () => {
224	  const worker = readFileSync(join(taskDir('tidy-issues'), 'task.md'), 'utf8');
225	  assert.match(worker, /\bunchanged\b/,
226	    'tidy-issues/task.md does not say what an unchanged verdict means for its tracker');
227	});
228	
229	// The strongest completion signal an issue can carry is its own checklist, fully
230	// ticked — and it is a claim by the author, not proof, so it enters the
231	// close-if-implemented rung rather than short-circuiting it (#1087).
232	test('single-issue-triage: a fully-ticked checklist prompts a completion check, and a partial one does not', () => {
233	  const skill = readFileSync(join(PACK_DIR, 'skills/single-issue-triage/SKILL.md'), 'utf8');
234	  assert.match(skill, /every checkbox .*ticked/i,
235	    'single-issue-triage never reads the issue body\'s checkboxes');
236	  assert.match(skill, /a claim.*not proof/i,
237	    'a ticked checklist is treated as proof of completion, bypassing the verify-against-main safeguard');
238	  assert.match(skill, /partially[- ]ticked/i,
239	    'the skill does not say a partially-ticked list is not a completion signal');
240	});
241	
242	// A manual-steps issue (a console setting, a routine only a human can touch) has no
243	// repo-side artifact to verify against, so verify-against-`main` alone would send
244	// every one of them to `comment` forever.
245	test('single-issue-triage: an ask with no repo-side artifact closes on the author\'s own ticks', () => {
246	  const skill = readFileSync(join(PACK_DIR, 'skills/single-issue-triage/SKILL.md'), 'utf8');
247	  assert.match(skill, /no repo-side artifact/i,
248	    'the skill leaves a manual-steps issue with no closing condition but main, which can never carry it');
249	});
250

