1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { readdirSync, existsSync, readFileSync } from 'node:fs';
4	import { join, dirname } from 'node:path';
5	import { fileURLToPath } from 'node:url';
6	import pack from '../pack.mjs';
7	import tidyIssues from '../tasks/tidy-issues/task.mjs';
8	import tidyPrs from '../tasks/tidy-prs/task.mjs';
9	
10	const PACK_DIR = join(dirname(fileURLToPath(import.meta.url)), '../../../packs/tidy-repo');
11	const taskDir = (id) => join(PACK_DIR, 'tasks', id);
12	
13	// The scheduler's signal bundle, in the shapes the collectors produce.
14	const S = (over = {}) => ({
15	  prs: { open: [], touched: [] },
16	  issues: { open: [], touched: [] },
17	  branches: { names: [], touched: [] },
18	  commits: { substantiveChange: false },
19	  ...over,
20	});
21	
22	test('tidy-repo is a declared pack (no fingerprint) with its skills; its tasks are not pack.mjs slots', () => {
23	  // No fingerprint is stated by saying nothing — the loader resolves an undeclared
24	  // `detect` to null.
25	  assert.equal(pack.detect, undefined);
26	  // The tasks moved out of the manifest: the repo's scheduler finds
27	  // tasks/<name>/task.mjs structurally (#394).
28	  assert.equal(pack.run_daily, undefined);
29	  assert.deepEqual(
30	    readdirSync(join(PACK_DIR, 'skills')).sort(),
31	    ['single-branch-status', 'single-issue-triage', 'single-pr-status'],
32	    'the worker skills are bundled in this pack\'s own skills/'
33	  );
34	});
35	
36	test('one task per tidy dimension — the single repo-tidy pass is split three ways', () => {
37	  assert.deepEqual(readdirSync(join(PACK_DIR, 'tasks')).sort(), ['tidy-branches', 'tidy-issues', 'tidy-prs']);
38	});
39	
40	test('every tidy task: id matches its dir, sonnet, outcome none, bounded, worker doc present', () => {
41	  for (const t of [tidyIssues, tidyPrs, tidyBranches]) {
42	    assert.ok(existsSync(taskDir(t.id)), `${t.id} has no task directory of its own`);
43	    assert.equal(t.agent_model, 'sonnet');    // landed-status / implemented-in-main are judgment calls
44	    assert.equal(t.expected_outcome, 'none'); // no tidy dimension ever opens or merges a PR
45	    assert.ok(Number.isInteger(t.agent_execution_timeout) && t.agent_execution_timeout > 0);
46	    assert.ok(existsSync(join(taskDir(t.id), t.agent_instructions)), `worker doc missing: ${t.id}/${t.agent_instructions}`);
47	  }
48	});
49	
50	// --- tidy-issues: the acting dimension, daily, narrow ------------------------
51	
52	test('tidy-issues: daily, and its signals are exactly the two triggers that change an issue verdict', () => {
53	  assert.equal(tidyIssues.id, 'tidy-issues');
54	  assert.equal(tidyIssues.frequency, 'daily'); // the one dimension that ACTS, so latency matters
55	  assert.deepEqual(tidyIssues.precondition_signals, ['issues', 'commits']);
56	});
57	
58	test('tidy-issues: scope is the touched issues only — a PR or branch moving is not its business', () => {
59	  const v = tidyIssues.precondition(S({ issues: { open: [{ number: 3 }, { number: 5 }], touched: [5] } }));
60	  assert.equal(v.run, true);
61	  assert.match(v.context.join(' '), /Issues to triage: #5\./);
62	  assert.doesNotMatch(v.context.join(' '), /#3/); // untouched, and main didn't move
63	
64	  // Activity in the other dimensions never wakes this task.
65	  assert.equal(tidyIssues.precondition(S({ prs: { open: [{ number: 7 }], touched: [7] } })).run, false);
66	  assert.equal(tidyIssues.precondition(S({ branches: { names: ['main', 'feat-x'], touched: ['feat-x'] } })).run, false);
67	});
68	
69	test('tidy-issues: a substantive main move widens an already-triggered run to every open issue', () => {
70	  const v = tidyIssues.precondition(S({
71	    issues: { open: [{ number: 3 }, { number: 5 }], touched: [5] },
72	    commits: { substantiveChange: true },
73	  }));
74	  assert.equal(v.run, true);
75	  assert.match(v.reason, /substantively/);
76	  assert.match(v.context.join(' '), /Issues to triage: #3, #5\./); // #3 is untouched, and still in scope
77	});
78	
79	// The gate the owner asked for: nothing new in the window → don't go over the
80	// existing ones. A moving `main` is not an issue moving, and on any active repo it
81	// moves substantively most days — so widening on it ALONE re-triaged every open
82	// issue daily, which is the failure this asserts against.
83	test('tidy-issues: a substantive main move alone never wakes the task', () => {
84	  const v = tidyIssues.precondition(S({
85	    issues: { open: [{ number: 3 }, { number: 5 }], touched: [] },
86	    commits: { substantiveChange: true },
87	  }));
88	  assert.equal(v.run, false);
89	  assert.match(v.reason, /no issues touched/);
90	});
91	
92	test('tidy-issues: silent on a quiet repo, and on a substantive move with no open issues', () => {
93	  assert.equal(tidyIssues.precondition(S()).run, false);
94	  assert.equal(tidyIssues.precondition(S({ commits: { substantiveChange: true } })).run, false);
95	});
96	
97	// --- tidy-prs: assess-only, weekly, full every run --------------------------
98	
99	test('tidy-prs: weekly (the full sweep is the declaration) over the prs signal alone', () => {
100	  assert.equal(tidyPrs.id, 'tidy-prs');
101	  assert.equal(tidyPrs.frequency, 'weekly');
102	  assert.deepEqual(tidyPrs.precondition_signals, ['prs']);
103	});
104	
105	test('tidy-prs: touched-ness gates the sweep but never narrows it — scope stays every open PR', () => {
106	  const v = tidyPrs.precondition(S({ prs: { open: [{ number: 7 }, { number: 9 }], touched: [9] } }));
107	  assert.equal(v.run, true);
108	  assert.match(v.reason, /full sweep over 2 open PR/);
109	  assert.match(v.context.join(' '), /PRs to assess.*#7, #9/); // #7 is untouched, and still assessed
110	  assert.match(v.context.join(' '), /read-only/);
111	});
112	
113	// The gate the owner asked for: an unchanged set of open PRs is last run's picture,
114	// and re-deriving it rewrites the tracker with itself.
115	test('tidy-prs: open PRs that nothing touched in the window are not re-swept', () => {
116	  const v = tidyPrs.precondition(S({ prs: { open: [{ number: 7 }, { number: 9 }], touched: [] } }));
117	  assert.equal(v.run, false);
118	  assert.match(v.reason, /no PR opened or updated in the window/);
119	});
120	
121	test('tidy-prs: no open PRs, no run', () => {
122	  assert.equal(tidyPrs.precondition(S()).run, false);
123	});
124	
125	// The `prs` signal also carries recently-MERGED PRs (for growth-extract). A merged
126	// PR is not something this sweep can recommend closing, so it must stay out of the
127	// target set entirely — the reason merged PRs live in their own field rather than
128	// being folded into `open`.
129	test('tidy-prs: merged PRs on the signal never enter the sweep', () => {
130	  const merged = { merged: [{ number: 42, title: 'landed last night' }] };
131	  assert.equal(tidyPrs.precondition(S({ prs: { open: [], touched: [], ...merged } })).run, false);
132	  // A merged PR is not a touch either: it cannot trigger the sweep on its own.
133	  assert.equal(tidyPrs.precondition(S({ prs: { open: [{ number: 7 }], touched: [], ...merged } })).run, false);
134	  const v = tidyPrs.precondition(S({ prs: { open: [{ number: 7 }], touched: [7], ...merged } }));
135	  assert.match(v.reason, /over 1 open PR/);
136	  assert.doesNotMatch(v.context.join(' '), /#42/);
137	});
138	
139	// --- tidy-branches: assess-only, weekly, full every run ---------------------
140	
141	test('tidy-branches: weekly (the full sweep is the declaration) over the branches signal alone', () => {
142	  assert.equal(tidyBranches.id, 'tidy-branches');
143	  assert.equal(tidyBranches.frequency, 'weekly');
144	  assert.deepEqual(tidyBranches.precondition_signals, ['branches']);
145	});
146	
147	test('tidy-branches: scope is every branch past the presumed default', () => {
148	  const v = tidyBranches.precondition(S({ branches: { names: ['main', 'feat-x', 'fix-y'], touched: ['fix-y'] } }));
149	  assert.equal(v.run, true);
150	  assert.match(v.reason, /full sweep over 2 branch/);
151	  assert.match(v.context.join(' '), /Branches to assess.*feat-x, fix-y/); // feat-x didn't move, and is still assessed
152	  assert.doesNotMatch(v.context.join(' '), /main/);
153	});
154	
155	// The gate the owner asked for. Branches are the dimension where it was structurally
156	// impossible before: the signal carried names and nothing else, so "is any of this
157	// new" had no answer and the sweep ran over the same pile every week.
158	test('tidy-branches: a standing pile of branches that nothing moved is not re-swept', () => {
159	  const v = tidyBranches.precondition(S({ branches: { names: ['main', 'feat-x', 'fix-y'], touched: [] } }));
160	  assert.equal(v.run, false);
161	  assert.match(v.reason, /no branch created or moved in the window/);
162	
163	  // A move on the default branch or an infra branch is not branch work either — it
164	  // is `main` advancing and the log stream growing, which happens on every repo
165	  // most days and would defeat the gate outright.
166	  assert.equal(tidyBranches.precondition(S({
167	    branches: { names: ['main', 'conversation-logs', 'feat-x'], touched: ['main', 'conversation-logs'] },
168	  })).run, false);
169	});
170	
171	test('tidy-branches: ignores the orphan conversation-logs and the maintenance delivery branch', () => {
172	  // conversation-logs is a claudinite-growth log stream and
173	  // claudinite/maintenance is Claudinite's own delivery branch — never project
174	  // work, so neither may reach the branch review.
175	  const v = tidyBranches.precondition(S({
176	    branches: { names: ['main', 'conversation-logs', 'claudinite/maintenance', 'feat-x'], touched: ['feat-x'] },
177	  }));
178	  assert.equal(v.run, true);
179	  assert.match(v.context.join(' '), /Branches to assess.*feat-x/);
180	  assert.doesNotMatch(v.context.join(' '), /conversation-logs|claudinite\/maintenance/);
181	
182	  // A repo whose only non-default branches are those two has no branch work at all.
183	  assert.equal(tidyBranches.precondition(S({ branches: { names: ['master', 'conversation-logs'], touched: ['conversation-logs'] } })).run, false);
184	  assert.equal(tidyBranches.precondition(S()).run, false);
185	});
186	
187	// --- the trackers: one per task, never a shared body ------------------------
188	
189	test('each worker reconciles its OWN tracker by exact title — three tasks never race on one body', () => {
